package org.yapyap.orchestrator.file.io

import kotlinx.io.files.Path
import kotlinx.io.files.SystemTemporaryDirectory
import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals
import kotlin.uuid.Uuid

/**
 * Step 7 (JVM): chunk-shaped I/O boundary over `FileChannel`.
 */
class JvmFileAccessTest {
    private val access = JvmFileAccess()

    private fun tempPath(name: String): Path {
        val dir = Path(SystemTemporaryDirectory.toString(), "yapyap-file-io-${Uuid.random()}")
        access.createDirectories(dir)
        return Path(dir.toString(), name)
    }

    @Test
    fun positionedRead_insideLargeSparseFile_skipsPrefix() {
        val path = tempPath("sparse.bin")
        // 16 MiB sparse: only the tail page is written.
        val total = 16L * 1024L * 1024L
        val markerOffset = 9L * 1024L * 1024L + 123L
        val marker = ByteArray(4096) { (it * 7).toByte() }
        access.openAppendWriter(path, null).use { w ->
            w.truncate(total)
            // Move to marker via truncate+append is append-only; write marker by
            // positioning through a second handle is test-only. Here we fake the
            // sparse layout by truncating then writing the marker at the end and
            // asserting a positioned read at an interior offset skips the prefix.
            w.truncate(markerOffset)
            w.write(marker)
            w.flushAndSync()
            assertEquals(markerOffset + marker.size, w.size())
        }
        access.openPositionedReader(path, startOffset = 0).use { r ->
            assertEquals(markerOffset + marker.size, r.size())
            val buf = ByteArray(marker.size)
            var off = 0
            while (off < buf.size) {
                val n = r.readAt(markerOffset + off, buf, off, buf.size - off)
                check(n > 0) { "unexpected EOF" }
                off += n
            }
            assertContentEquals(marker, buf)
            // Prefix reads as zeros (sparse hole).
            val hole = ByteArray(16)
            val n = r.readAt(1024L, hole, 0, hole.size)
            assertEquals(hole.size, n)
            assertContentEquals(ByteArray(16), hole)
        }
    }

    @Test
    fun appendWriter_truncatesTornAppendToLength() {
        val path = tempPath("torn.bin")
        access.openAppendWriter(path, null).use { w ->
            w.write(ByteArray(100) { it.toByte() })
            w.flushAndSync()
            assertEquals(100L, w.size())
            w.truncate(40L)
            assertEquals(40L, w.size())
            w.flushAndSync()
        }
        // Reopen truncates anything beyond the persisted length (crash recovery).
        access.openAppendWriter(path, truncateToLength = 40L).use { w ->
            assertEquals(40L, w.size())
        }
        access.openPositionedReader(path).use { r ->
            assertEquals(40L, r.size())
            val buf = ByteArray(40)
            var off = 0
            while (off < buf.size) {
                val n = r.readAt(off.toLong(), buf, off, buf.size - off)
                check(n > 0)
                off += n
            }
            assertContentEquals(ByteArray(40) { it.toByte() }, buf)
        }
    }

    @Test
    fun flush_syncsOncePerCall_andIsDurable() {
        val path = tempPath("durable.bin")
        val payload = ByteArray(65536) { (it % 251).toByte() }
        access.openAppendWriter(path, null).use { w ->
            w.write(payload)
            // One flush == one fsync (single `force(true)` in JvmAppendHandle);
            // observable effect: bytes survive close + reopen.
            w.flushAndSync()
        }
        access.openPositionedReader(path).use { r ->
            assertEquals(payload.size.toLong(), r.size())
            val buf = ByteArray(payload.size)
            var off = 0
            while (off < buf.size) {
                val n = r.readAt(off.toLong(), buf, off, buf.size - off)
                check(n > 0)
                off += n
            }
            assertContentEquals(payload, buf)
        }
    }
}

package org.yapyap.orchestrator.file

import kotlinx.serialization.Serializable
import org.yapyap.protocol.SMALL_FILE_MAX_BYTES
import kotlin.time.Duration
import kotlin.time.Duration.Companion.seconds

/**
 * File config (design §15). Lives next to the file machinery; `wiring`
 * aggregates it into `RuntimeConfig` and checks the cross-layer invariants.
 */
@Serializable
internal data class FileServiceConfig(
    /** "Keep a copy" default threshold; at or below → copy, above → reference. */
    val copyIntoStoreMaxBytes: Long = SMALL_FILE_MAX_BYTES,
    /** Quota over COPY descriptors only; references are never deleted by retention. */
    val storeQuotaBytes: Long = 1024L * 1024L * 1024L,
    /** Staging bound (design §8): chunks beyond P that cannot extend it are DEFERred. */
    val maxStagedBytes: Long = 32L * 1024L * 1024L,
    /** Block mismatches before a receive FAILs (design §8). */
    val fileHashRetryLimit: Int = 3,
    /** Large files at or below this are fetched automatically (design §8). */
    val autoDownloadMaxBytes: Long = 250L * 1024L * 1024L,
    /** Checkpoint cadence: append, one fsync, one P commit (design §8). */
    val fileCheckpointBytes: Long = 8L * 1024L * 1024L,
    val fileCheckpointInterval: Duration = 2.seconds,
) {
    init {
        require(copyIntoStoreMaxBytes >= 0) { "copyIntoStoreMaxBytes must be >= 0" }
        require(storeQuotaBytes > 0) { "storeQuotaBytes must be > 0" }
        require(maxStagedBytes > 0) { "maxStagedBytes must be > 0" }
        require(fileHashRetryLimit > 0) { "fileHashRetryLimit must be > 0" }
        require(autoDownloadMaxBytes >= 0) { "autoDownloadMaxBytes must be >= 0" }
        require(fileCheckpointBytes > 0) { "fileCheckpointBytes must be > 0" }
        require(fileCheckpointInterval > Duration.ZERO) { "fileCheckpointInterval must be > 0" }
        require(maxStagedBytes >= fileCheckpointBytes) {
            "maxStagedBytes must hold a checkpoint's worth"
        }
    }
}

