package org.yapyap.orchestrator.file

import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.withContext
import org.yapyap.persistence.YapYapDatabase
import org.yapyap.persistence.databaseDispatcher
import org.yapyap.protocol.FileId
import kotlin.time.Instant

internal fun encodeBlockHashes(hashes: List<ByteArray>): ByteArray {
    hashes.forEach { require(it.size == 32) { "block hash must be 32 bytes" } }
    val out = ByteArray(hashes.size * 32)
    hashes.forEachIndexed { i, h -> h.copyInto(out, i * 32) }
    return out
}

internal fun decodeBlockHashes(blob: ByteArray): List<ByteArray> {
    require(blob.size % 32 == 0) { "block_hashes blob must be a multiple of 32 but was ${blob.size}" }
    return List(blob.size / 32) { i -> blob.copyOfRange(i * 32, (i + 1) * 32) }
}

/**
 * Owner of `file_descriptors` (guide §4). Generated `fileQueries` stay here.
 */
internal interface FileDescriptorStore {
    suspend fun upsert(descriptor: FileDescriptor)
    suspend fun findById(fileId: FileId): FileDescriptor?
    suspend fun deleteById(fileId: FileId)
    suspend fun setStatus(fileId: FileId, status: FileDescriptorStatus)
    suspend fun copyDescriptorsOldestFirst(): List<FileDescriptor>
    suspend fun copyBytesTotal(): Long
}

internal class DefaultFileDescriptorStore(
    database: YapYapDatabase,
    private val dbDispatcher: CoroutineDispatcher = databaseDispatcher,
) : FileDescriptorStore {
    private val queries = database.fileQueries

    override suspend fun upsert(descriptor: FileDescriptor) = withContext(dbDispatcher) {
        queries.insertFileDescriptor(
            file_id = descriptor.fileId,
            file_name = descriptor.fileName,
            mime_type = descriptor.mimeType,
            total_bytes = descriptor.totalBytes,
            block_size = descriptor.blockSize,
            block_hashes = encodeBlockHashes(descriptor.blockHashes),
            storage = descriptor.storage,
            path = descriptor.path,
            status = descriptor.status,
            created_at = descriptor.createdAt,
        )
    }

    override suspend fun findById(fileId: FileId): FileDescriptor? = withContext(dbDispatcher) {
        queries.selectFileDescriptorById(fileId).executeAsOneOrNull()?.toDescriptor()
    }

    override suspend fun deleteById(fileId: FileId) = withContext(dbDispatcher) {
        queries.deleteFileDescriptorById(fileId)
    }

    override suspend fun setStatus(fileId: FileId, status: FileDescriptorStatus) = withContext(dbDispatcher) {
        queries.updateFileDescriptorStatus(status, fileId)
    }

    override suspend fun copyDescriptorsOldestFirst(): List<FileDescriptor> = withContext(dbDispatcher) {
        queries.selectCopyDescriptorsOrderedByCreated().executeAsList().map { it.toDescriptor() }
    }

    override suspend fun copyBytesTotal(): Long = withContext(dbDispatcher) {
        queries.sumCopyBytes().executeAsOneOrNull() ?: 0L
    }

    private fun org.yapyap.persistence.File_descriptors.toDescriptor(): FileDescriptor = FileDescriptor(
        fileId = file_id,
        fileName = file_name,
        mimeType = mime_type,
        totalBytes = total_bytes,
        blockSize = block_size.toInt(),
        blockHashes = decodeBlockHashes(block_hashes),
        storage = storage,
        path = path,
        status = status,
        createdAt = created_at,
    )
}

package org.yapyap.orchestrator.file

import kotlinx.coroutines.withContext
import kotlinx.coroutines.Dispatchers
import kotlinx.io.files.Path
import org.yapyap.crypto.primitives.CryptoProvider
import org.yapyap.orchestrator.file.io.FileAccess
import org.yapyap.protocol.FileId
import org.yapyap.protocol.blockSizeFor
import kotlin.time.Clock

/**
 * Permanent attachment store (design §10).
 *
 * - COPY: bytes live under the store dir as `<fileId hex>`, hashed in the same
 *   pass as the copy. Survives the original being deleted. Quota-managed with
 *   LRU over copies only.
 * - REFERENCE: the original stays in place and is hashed in place. Outside the
 *   quota, never deleted by retention. A moved/deleted/edited original is
 *   caught by the block check while serving (step 9) and marked SOURCE_LOST.
 *
 * The import result carries the `fileId` and block list. The GUI only gets
 * paths and metadata vended back (guide §2, design §10).
 */
internal interface FileStore {
    suspend fun import(
        source: FileImportSource,
        fileName: String,
        mimeType: String?,
        keepCopy: Boolean,
    ): FileDescriptor

    suspend fun resolve(fileId: FileId): FileDescriptor?

    suspend fun markSourceLost(fileId: FileId)
}

internal class DefaultFileStore(
    private val descriptors: FileDescriptorStore,
    private val crypto: CryptoProvider,
    private val files: FileAccess,
    private val storeDirectory: Path,
    private val config: FileServiceConfig,
    private val clock: Clock = Clock.System,
) : FileStore {
    override suspend fun import(
        source: FileImportSource,
        fileName: String,
        mimeType: String?,
        keepCopy: Boolean,
    ): FileDescriptor = withContext(Dispatchers.IO) {
        require(fileName.isNotBlank()) { "fileName must not be blank" }
        val totalBytes = sourceSize(source)
            ?: throw IllegalArgumentException("import source is missing")
        val blockSize = blockSizeFor(totalBytes)
        val copy = keepCopy

        if (!copy) {
            val hashes = hashSource(source, totalBytes, blockSize, writeTo = null)
            val fileId = FileIds.fileIdForBlocks(crypto, totalBytes, blockSize, hashes)
            val existing = descriptors.findById(fileId)
            if (existing != null) return@withContext existing
            val descriptor = FileDescriptor(
                fileId = fileId,
                fileName = fileName,
                mimeType = mimeType,
                totalBytes = totalBytes,
                blockSize = blockSize,
                blockHashes = hashes,
                storage = FileStorage.REFERENCE,
                path = when (source) {
                    is FileImportSource.PathSource -> source.path.toString()
                    is FileImportSource.ContentUriSource -> source.uri
                },
                status = FileDescriptorStatus.HELD,
                createdAt = clock.now(),
            )
            descriptors.upsert(descriptor)
            return@withContext descriptor
        }

        // Copy mode: stream source -> temp store file while hashing per block.
        files.createDirectories(storeDirectory)
        val tmp = Path(storeDirectory.toString(), "tmp-${clock.now().toEpochMilliseconds()}-${fileName.hashCode()}")
        val hashes: List<ByteArray>
        try {
            hashes = hashSource(source, totalBytes, blockSize, writeTo = tmp)
        } catch (e: Exception) {
            runCatching { files.delete(tmp) }
            throw e
        }
        val fileId = FileIds.fileIdForBlocks(crypto, totalBytes, blockSize, hashes)
        val existing = descriptors.findById(fileId)
        if (existing != null) {
            runCatching { files.delete(tmp) }
            return@withContext existing
        }
        val final = Path(storeDirectory.toString(), fileId.value)
        if (files.exists(final)) {
            runCatching { files.delete(tmp) }
        } else {
            files.move(tmp, final)
        }
        val descriptor = FileDescriptor(
            fileId = fileId,
            fileName = fileName,
            mimeType = mimeType,
            totalBytes = totalBytes,
            blockSize = blockSize,
            blockHashes = hashes,
            storage = FileStorage.COPY,
            path = final.toString(),
            status = FileDescriptorStatus.HELD,
            createdAt = clock.now(),
        )
        descriptors.upsert(descriptor)
        enforceQuota()
        descriptors.findById(fileId) ?: descriptor
    }

    override suspend fun resolve(fileId: FileId): FileDescriptor? = descriptors.findById(fileId)

    override suspend fun markSourceLost(fileId: FileId) {
        descriptors.setStatus(fileId, FileDescriptorStatus.SOURCE_LOST)
    }

    private suspend fun sourceSize(source: FileImportSource): Long? = when (source) {
        is FileImportSource.PathSource -> files.fileSize(source.path)
        is FileImportSource.ContentUriSource -> files.contentSize(source.uri)
    }

    /**
     * Hashes every block of [source] in order. When [writeTo] is set the bytes
     * are also appended to that store path in the same pass (copy mode).
     */
    private suspend fun hashSource(
        source: FileImportSource,
        totalBytes: Long,
        blockSize: Int,
        writeTo: Path?,
    ): List<ByteArray> {
        if (totalBytes == 0L) {
            writeTo?.let { t ->
                files.openAppendWriter(t, null).use { it.flushAndSync() }
            }
            return emptyList()
        }
        val writer = writeTo?.let { files.openAppendWriter(it, null) }
        try {
            val hashes = mutableListOf<ByteArray>()
            var hasher = crypto.sha256Hasher()
            var inBlock = 0L
            var remaining = totalBytes
            var offset = 0L
            val buf = ByteArray(128 * 1024)
            while (remaining > 0) {
                val n = readSource(source, offset, buf, minOf(buf.size.toLong(), remaining).toInt())
                if (n <= 0) throw IllegalArgumentException("import source ended early at offset $offset")
                hasher.update(buf, 0, n)
                writer?.write(buf, 0, n)
