            writer?.flushAndSync()
            return hashes
        } finally {
            runCatching { writer?.close() }
        }
    }

    private fun readSource(source: FileImportSource, offset: Long, buf: ByteArray, length: Int): Int =
        when (source) {
            is FileImportSource.PathSource -> files.openPositionedReader(source.path).use {
                it.readAt(offset, buf, 0, length)
            }
            is FileImportSource.ContentUriSource -> {
                val reader = files.openContentPositionedReader(source.uri)
                    ?: throw IllegalArgumentException("content URI cannot be read: ${source.uri}")
                reader.use { it.readAt(offset, buf, 0, length) }
