-- device wants but does not hold. The router owns the asking (file_request_attempts);
-- this row is the trigger state: PENDING (waiting out the grace period or the next
-- attempt) or UNAVAILABLE (every candidate declined — terminal until a new message or
-- a user re-open re-arms it). STALLED/EXPIRED receives re-open through this table.
CREATE TABLE pending_file_requests (
    file_id TEXT AS FileId NOT NULL PRIMARY KEY,
    status TEXT AS PendingFileRequestStatus NOT NULL,
    next_attempt_at INTEGER AS Instant NOT NULL,
    updated_at INTEGER AS Instant NOT NULL
);

