/**
 * Durable held coverage for building a sealed REQUEST (design §3.2, §9): the contiguous
 * prefix plus the capped missing ranges beyond it. Heavy fragmentation degrades to
 * contiguous-only — a coarser serve with more duplicates, still correct. Null when the
 * file needs no request: already READY (the requester's loop drops its row).
 */
suspend fun heldCoverage(fileId: FileId): FileCoverage? = lock.withLock {
    val row = try {
        receives.find(fileId)
    } catch (e: Exception) {
        if (e is kotlinx.coroutines.CancellationException) throw e
        null
    } ?: return FileCoverage(0L, emptyList())
    if (row.status == FileReceiveStatus.READY) return null

